    private static TaskRootFacts TaskCaptureExhaustRootFacts(CombatState live, CombatPredictionSimulator shadow)
    {
        var combat = (SimulatedCombatState)shadow.State.CombatState;
        List<TaskSourceIdentity> sources = [];
        List<TaskDelegateIdentity> delegates = [];
        static CardModel[] AllCards(CombatState state) => ((IEnumerable)typeof(CombatState).GetField("_allCards",
            BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(state)!).Cast<CardModel>().ToArray();
        void Add(AbstractModel model, string location)
        {
            sources.Add(new(location, model.GetType().FullName!, model.Id.Entry));
            for (Type? type = model.GetType(); type != null && typeof(AbstractModel).IsAssignableFrom(type); type = type.BaseType)
            foreach (EventInfo ev in type.GetEvents(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
            {
                FieldInfo? field = type.GetField(ev.Name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly);
                if (field == null) throw new InvalidOperationException("Unresolved event field: " + type.FullName + "." + ev.Name);
                if (field.GetValue(model) is Delegate observer)
                    foreach (Delegate callback in observer.GetInvocationList())
                        delegates.Add(new(model.GetType().FullName!, ev.Name,
                            callback.Method.DeclaringType?.FullName + "." + callback.Method.Name,
                            callback.Method.Module.Assembly.GetName().Name!));
            }
            if (model is CardModel card)
            {
                if (card.Enchantment is { } enchantment) Add(enchantment, location + "/enchantment");
                if (card.Affliction is { } affliction) Add(affliction, location + "/affliction");
            }
        }
        foreach (AbstractModel model in live.IterateHookListeners()) Add(model, "combat-listener");
        foreach (AbstractModel model in live.RunState.IterateHookListeners(live)) Add(model, "run-listener");
        HashSet<CardModel> piled = live.Players.Where(p => p.PlayerCombatState != null)
            .SelectMany(p => p.PlayerCombatState!.AllCards).ToHashSet();
        CardModel[] floating = AllCards(live).Where(card => !piled.Contains(card)).ToArray();
        foreach (CardModel card in floating) Add(card, "floating");
        // Explicit deck/pile inputs are recorded even when no current listener uses them.
        foreach (Player owner in live.Players)
        {
            foreach (CardModel card in owner.Deck.Cards) Add(card, "permanent-deck");
            foreach (CardModel card in owner.PlayerCombatState!.AllCards) Add(card, "combat-pile");
        }
        foreach (var card in combat.PendingReturningCards) Add(card.Preview, "pending-return");
        List<TaskPatchIdentity> patches = [];
        foreach (MethodBase target in Harmony.GetAllPatchedMethods().Where(method => method.Module == typeof(CardModel).Module))
        {
            Patches patchInfo = Harmony.GetPatchInfo(target)!;
            foreach (var group in AdaptedCardOnPlayMirrors.Groups(patchInfo))
            foreach (Patch patch in group.Patches)
                patches.Add(new(target.DeclaringType?.FullName + "." + target.Name,
                    target.Module.Assembly.GetName().Name!, group.Kind.ToString(),
                    patch.PatchMethod.DeclaringType?.FullName + "." + patch.PatchMethod.Name,
                    patch.PatchMethod.Module.Assembly.GetName().Name!));
        }
        string? first = sources.FirstOrDefault(source => !TaskReviewedExhaustSourceTypes.Contains(source.RuntimeType)) is { } unknown
            ? unknown.Location + ":" + unknown.RuntimeType : null;
        return new(Array.AsReadOnly(sources.ToArray()), Array.AsReadOnly(delegates.Distinct().ToArray()),
            Array.AsReadOnly(patches.ToArray()), floating.Length, combat.RootRunModSubscriberCount,
            combat.RootCombatModSubscriberCount, combat.RootHasBaseLibCardModifiers,
            combat.AdaptedOnPlay is not null, first, false);
    }

    private async Task RunTaskExhaustRootAuditAsync(CombatState live, Player player)
    {
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        TaskRootFacts initial = TaskCaptureExhaustRootFacts(live, parent);
        if (initial.FirstUnreviewedSource != null) throw new InvalidOperationException(initial.FirstUnreviewedSource);
        string frozen = JsonSerializer.Serialize(initial);
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player), root.Forecast, root.StartTurnNumber).StateText
            + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string parentState = State(parent), liveState = ContinuationStamp.CaptureLive(live).StateText;
        var children = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        await Task.WhenAll(children.Select(child => Task.Run(() => {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            if (State(child) != parentState || JsonSerializer.Serialize(initial) != frozen)
                throw new InvalidOperationException("Frozen inventory or initial Fork differs.");
        })));
        if (State(parent) != parentState || ContinuationStamp.CaptureLive(live).StateText != liveState)
            throw new InvalidOperationException("Inventory/Fork mutated its parent or live.");
        CardModel observed = player.PlayerCombatState!.Hand.Cards[0];
        void UnknownEvent(AbstractModel _) { }
        observed.ExecutionFinished += UnknownEvent;
        TaskRootFacts withEvent;
        try { withEvent = TaskCaptureExhaustRootFacts(live, parent); }
        finally { observed.ExecutionFinished -= UnknownEvent; }
        if (!withEvent.Delegates.Any(d => d.Method.Contains("UnknownEvent", StringComparison.Ordinal)))
            throw new InvalidOperationException("Unknown event was missed.");
        // Explicit creation is not random generation; Eidolon is CanBeGeneratedInCombat=false.
        CardModel unknownFloating = live.CreateCard<Eidolon>(player);
        TaskRootFacts withFloating = TaskCaptureExhaustRootFacts(live, parent);
        if (withFloating.FloatingCards <= initial.FloatingCards || withFloating.FirstUnreviewedSource is not { } rejected
            || !rejected.Contains("Eidolon", StringComparison.Ordinal))
            throw new InvalidOperationException("Unknown floating source was missed.");
        if (JsonSerializer.Serialize(initial) != frozen || State(parent) != parentState)
            throw new InvalidOperationException("Later live changes contaminated the captured inventory/parent.");
        // Removing the investigation object from native registration avoids leaving test sources.
        live.RemoveCard(unknownFloating);
        _completedChecks.Add("ExhaustRootAudit:ActualGeneratedSilentBoss:AllPilesDeckFloatingRunListeners:NativePatches:UnknownEventDetected:UnknownFloatingRejected:SixteenInitialForks:FrozenMetadataAndParentIsolation");
        _completedChecks.Add("TASK_EXHAUST_ROOT " + JsonSerializer.Serialize(new { initial, withEvent,
            withFloating, forkCount = children.Length, actualPrunes = 0, isWholeOrderCertificate = false }));
    }
