internal static IReadOnlyList<IModelCapability> Create(AbstractModel owner)
{
	ArgumentNullException.ThrowIfNull(owner, "owner");
	ModelCapabilityList modelCapabilityList = new ModelCapabilityList();
	if (owner is IModelCapabilitySource provider)
	{
		RunProvider(provider, modelCapabilityList);
	}
	ModelDefaultCapabilityModifierEntry[] modifiers = GetModifiers(owner);
	foreach (ModelDefaultCapabilityModifierEntry modifier in modifiers)
	{
		RunModifier(owner, modifier, modelCapabilityList);
	}
	return modelCapabilityList.ToArray();
}

