private static ModelDefaultCapabilityModifierEntry[] GetModifiers(Type ownerType)
{
	Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> dictionary = Volatile.Read(in _modifiersByOwnerType);
	if (dictionary.TryGetValue(ownerType, out var value))
	{
		return value;
	}
	using (SyncRoot.EnterScope())
	{
		dictionary = Volatile.Read(in _modifiersByOwnerType);
		if (dictionary.TryGetValue(ownerType, out value))
		{
			return value;
		}
		value = (from entry in Modifiers
			where entry.OwnerType.IsAssignableFrom(ownerType)
			orderby entry.Order, entry.RegistrationOrder
			select entry).ToArray();
		Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> value2 = new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>(dictionary) { [ownerType] = value };
		Volatile.Write(ref _modifiersByOwnerType, value2);
		return value;
	}

